let plotRoomTab='grow';
const plotRoomTabs={grow:'🌱 Выращивать',build:'🪵 Обустроить',camera:'📹 Камеры и архив',harvest:'🧺 Урожай',activity:'📋 Ход работ'};
const roomRules=allowedStates;
function currentRoomPlot(){const m=location.hash.match(/^#bed-(\d+)$/);return m&&cloud?.plots.find(p=>p.id===Number(m[1])&&p.mine)}
function roomTile(icon,title,description,action,meta='',disabled=false){return `<button class="room-action" ${disabled?'disabled':''} onclick="${action}"><span class="room-action-icon">${icon}</span><strong>${title}</strong><span>${description}</span><small>${meta}</small></button>`}
function roomService(p,code,icon,title,description){const s=opsData?.services.find(s=>s.code===code),allowed=roomRules[code]?.includes(p.growing_state);const plan=opsData?.plans.find(x=>x.plot_id===p.id);const needsPlan=['plant','water','feed'].includes(code)&&!plan;const busy=opsData?.orders.some(o=>o.plot_id===p.id&&!['done','cancelled'].includes(o.status));const lease=cloud?.rentals?.find(r=>r.plot_id===p.id&&r.status==='active');const expired=lease&&new Date(lease.ends_at)<=new Date();const last=opsData?.orders.filter(o=>o.plot_id===p.id&&o.service_code===code&&o.status==='done'&&!o.is_simulation).sort((a,b)=>Date.parse(b.finished_at)-Date.parse(a.finished_at))[0];const careReason=serviceReason(code,p,plan,last?.finished_at);const reason=expired?'Сначала продлите аренду':!s?.enabled?'Услуга пока закрыта':careReason?careReason:busy?'Дождитесь текущей работы':'';return roomTile(icon,title,description,`roomOrder(${p.id},'${code}')`,reason||`${money(s.price_kopecks)} · ~${s.duration_minutes} мин.`,!!reason)}
function roomRequest(p,kind,icon,title,desc){return roomTile(icon,title,desc,`lifeRequest('${kind}',${p.id})`,'Цена и сроки после согласования')}
function plotRoom(){const p=currentRoomPlot();if(!account)return authResolved?heading('Войдите в своё хозяйство','')+'<button class="btn" onclick="profile()">Войти</button>':'<section class="farm-loading" role="status">🌱 Открываем ваше хозяйство…</section>';if(!p)return heading('Грядка не найдена в вашем хозяйстве','')+'<a class="btn" href="#home">К хозяйству</a>';const orders=(opsData?.orders||[]).filter(o=>o.plot_id===p.id),rental=cloud.rentals?.find(r=>r.plot_id===p.id&&r.status==='active');let content='';if(plotRoomTab==='grow')content=`<div class="room-actions">${roomService(p,'inspect','🔎','Осмотр по желанию','Дополнительная проверка при вопросах или проблемах')}${roomService(p,'prepare','🪏','Подготовить почву','Подготовить грядку перед посадкой')}${roomService(p,'plant','🌱','Посеять семена','Посадка по утверждённому плану')}${roomService(p,'water','💧','Полить','Полив с учётом плана и интервалов')}${roomService(p,'feed','🌿','Подкормить','Материал и дозировку определяет садовник')}${roomService(p,'weed','🌾','Прополоть','Убрать сорняки и освободить посадки')}${roomService(p,'loosen','🪏','Разрыхлить поверхность','По плану, сохраняя корни')}${roomService(p,'hill','🌿','Окучить','Только подходящую культуру по плану')}${roomRequest(p,'seedlings','🪴','Посадить рассаду','Выбрать рассаду вместо семян')}${roomRequest(p,'kit','🥗','Готовый набор','Салат, зелень или острый огород')}</div><p class="note">Недоступные действия откроются после необходимых предыдущих этапов. Цена работы фиксируется при выборе; время начала согласует садовник.</p>`;
if(plotRoomTab==='build')content=`<div class="room-actions">${roomRequest(p,'mulch','🍂','Укрыть мульчей','Подобрать материал для почвы')}${roomRequest(p,'soil','🧪','Проверить почву','Измерения и рекомендации')}${roomTile('🏷️','Моя табличка','Название и подпись на карточке',`sign(${p.id})`,'Цифровое оформление')}${roomTile('▦','Разделить на зоны','Распределить площадь между культурами',`roomZones(${p.id})`,'В пределах площади грядки')}</div>`;
if(plotRoomTab==='camera')content=`<div class="room-camera"><span>📹</span><h2>Окно в вашу грядку</h2><p>Проверьте прямой эфир. Если камера ещё не подключена, сообщим об этом.</p><button class="btn" onclick="camera(${p.id})">▷ Открыть камеру</button></div><div class="room-actions">${roomRequest(p,'archive','☁️','Облачный архив','Хранить записи и смотреть прошлые работы')}${roomRequest(p,'timelapse','🎞️','Таймлапс роста','Собрать историю роста в короткий ролик')}${roomRequest(p,'photo','📸','Свежие фотографии','Попросить крупный план посадок')}</div><p class="note">Архив и таймлапс требуют подключения записи. Оформление заявки само по себе не включает хранение видео.</p>`;
if(plotRoomTab==='harvest')content=`<div class="room-actions">${roomService(p,'harvest','🧺','Собрать урожай','Заказать сбор созревших продуктов')}${roomRequest(p,'ripeness','🍅','Выбрать спелость','Для еды сейчас или перевозки')}${roomTile('📦','Склад и партии','Условия хранения и паспорта урожая',"location.hash='warehouse'",'Все партии хозяйства')}${roomTile('🚚','Корзина домой','Доставка, подарки и благотворительность',"location.hash='lifecycle'",'Из принятого урожая')}</div>`;
if(plotRoomTab==='activity')content=orders.length?`<div class="grid">${orders.map(orderCard).join('')}</div>`:'<section class="panel empty"><h3>Здесь будет история заботы</h3><p>Выберите действие в разделе «Выращивать» — здесь появятся сроки, статус и результат.</p></section>';
return `<a class="room-back" href="#home">← Моё хозяйство</a><section class="room-hero"><div><span class="eyebrow">МОЯ ГРЯДКА №${p.id} · ${p.size} М²</span><h1>${esc(p.name)}</h1><p>${esc(p.crop||'Выберите культуру и план посадок')}</p><span class="pill">${growingLabels[p.growing_state]||'Нужен осмотр'}</span>${rental?`<p class="room-rental">Демоаренда до ${fmt(rental.ends_at)}</p>`:''}</div><div class="room-soil" aria-hidden="true">${['planted','growing','harvest_ready'].includes(p.growing_state)?Array.from({length:6},()=>`<span>${typeof cropDrawing==='function'?cropDrawing(p.crop,p.growing_state):'🌱'}</span>`).join(''):'<span class="empty-soil-label">Почва</span>'}</div></section><div class="room-tabs" role="tablist" aria-label="Разделы грядки">${Object.entries(plotRoomTabs).map(([k,t])=>`<button role="tab" aria-selected="${plotRoomTab===k}" class="${plotRoomTab===k?'selected':''}" onclick="plotRoomTab='${k}';render()">${t}${k==='activity'&&orders.length?' · '+orders.length:''}</button>`).join('')}</div><section role="tabpanel" aria-label="${plotRoomTabs[plotRoomTab]}">${content}</section>${account.role==='admin'?`<details class="panel room-admin"><summary>Управляющему: подтвердить состояние и план</summary><p>Отмечайте только результаты фактического осмотра.</p><div class="actions"><button class="btn light" onclick="inspectPlot(${p.id})">Осмотр участка</button><button class="btn light" onclick="carePlan(${p.id})">План ухода</button></div></details>`:''}`}
function roomOrder(plot,code){const s=opsData?.services.find(x=>x.code===code);if(!s)return;const key=crypto.randomUUID();formAsync(s.title+` · грядка №${plot}`,`<h3>${money(s.price_kopecks)} · ~${s.duration_minutes} мин.</h3><p>${esc(s.description||'')}</p>${code==='plant'?`<label>Семена или рассада из моих запасов<select name="supply" required>${(seasonData?.supplies||[]).filter(x=>Number(x.balance)>Number(x.reserved)).map(x=>`<option value="${x.id}">${esc(x.name)} · ${Number(x.balance)-Number(x.reserved)} ${esc(x.unit)}</option>`).join('')}</select></label><label>Количество в единицах запаса<input name="quantity" type="number" min="0.001" step="0.001" required></label>`:''}${code==='harvest'?'<label>Куда отправить урожай<select name="destination"><option value="home">Домой</option><option value="storage">На склад</option><option value="gift">В подарок</option><option value="charity">На благотворительность</option></select></label>':''}<label>Посадка<select name="cycle"><option value="">Определить, если посадка одна</option>${(seasonData?.cycles||[]).filter(c=>c.plot_id===plot&&!c.ended_on&&c.approved).map(c=>`<option value="${c.id}">${esc(c.crop)}</option>`).join('')}</select></label><p class="note">Садовник предложит время. После согласования доступна демооплата. Нажатие не означает, что физическая работа уже началась.</p><button class="btn">Выбрать «${esc(s.title)}»</button>`,async f=>{await api('order-create',{plot,service:code,key,cycle:f.get('cycle')||null,supply:f.get('supply')||null,quantity:Number(f.get('quantity')),destination:f.get('destination')});await loadOperations();plotRoomTab='activity';render();toast('Действие добавлено. Здесь появятся сроки.')})}
function roomZones(id){zoneForm();document.querySelector('#fields select[name=plot]').value=String(id)}
const beforeRoomRender=render;render=function(){beforeRoomRender();const p=currentRoomPlot();if(/^#bed-\d+$/.test(location.hash)){$('#app').innerHTML=plotRoom();$('#crumb').textContent=p?'ГРЯДКА №'+p.id:'ГРЯДКА';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#home'))}else if((location.hash==='#home'||!location.hash)&&account){document.querySelectorAll('#app .card').forEach(card=>{const action=card.querySelector('button[onclick^="care("]');if(!action)return;const id=Number(action.getAttribute('onclick').match(/\d+/)[0]);const area=card.querySelector('.plot-art');if(area){const link=document.createElement('a');link.href='#bed-'+id;link.className='room-card-link';link.setAttribute('aria-label','Открыть грядку №'+id);area.replaceWith(link);link.append(area)}const actions=card.querySelector('.actions');actions.innerHTML=`<a class="btn" href="#bed-${id}">Войти в грядку ↗</a>`;const title=card.querySelector('h3');title.innerHTML=`<a href="#bed-${id}">${esc(title.textContent)}</a>`})}};
addEventListener('hashchange',()=>{if(/^#bed-\d+$/.test(location.hash)){plotRoomTab='grow';if(account)loadOperations()}});setInterval(()=>{if(account&&currentRoomPlot()&&!document.hidden&&!modal.open)loadOperations()},30000);render();
